package com.abhi.ganasuno.ui

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.widget.EditText
import android.widget.Toast
import android.text.InputType
import com.abhi.ganasuno.data.*
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import java.util.concurrent.Executor

/** Public metadata is opt-in and separate from the existing playback engine. */
class PublicCatalogueTools(private val a:Activity,private val io:Executor){
    private var key=""
    private var generation=0
    private val regions=listOf("IN","US","GB","JP","KR","DE")
    private fun region()=regions[LibraryStore.option("country").coerceIn(0,regions.lastIndex)]
    private fun limit()=Batch16.homeLimit(LibraryStore.option("home_limit",30))
    private fun toast(s:String)=Toast.makeText(a,s,Toast.LENGTH_LONG).show()
    private fun choose(title:String,labels:List<String>,action:(Int)->Unit){if(labels.isEmpty()){toast("No results available");return};MaterialAlertDialogBuilder(a).setTitle(title).setItems(labels.toTypedArray()){_,i->action(i)}.setNegativeButton("Close",null).show()}
    private fun ask(title:String,secret:Boolean=false,action:(String)->Unit){val field=EditText(a).apply{setSingleLine(true);if(secret){isSaveEnabled=false;inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD}};MaterialAlertDialogBuilder(a).setTitle(title).setView(field).setNegativeButton("Cancel",null).setPositiveButton("Continue"){_,_->val value=field.text.toString().trim();if(secret)field.text.clear();action(value)}.show()}
    private fun withKey(action:(String)->Unit){if(key.isNotBlank()){action(key);return};ask("YouTube Data API key · session only",true){raw->if(Batch16.keyLooksValid(raw)){key=raw;action(raw)}else toast("Invalid API key format")}}
    private fun <T> task(action:(String)->T,done:(T)->Unit){withKey{k->val serial=++generation;toast("Fetching public metadata…");io.execute{val result=runCatching{action(k)};a.runOnUiThread{if(!a.isDestroyed&&!a.isFinishing&&serial==generation)result.onSuccess(done).onFailure{toast("Catalogue unavailable: check API key, quota, region or network")}}}}}
    private fun open(kind:String,id:String){runCatching{a.startActivity(Intent.createChooser(Intent(Intent.ACTION_VIEW,Uri.parse(Batch16.publicUrl(kind,id))).addCategory(Intent.CATEGORY_BROWSABLE),"Open on YouTube or browser").putExtra(Intent.EXTRA_EXCLUDE_COMPONENTS,arrayOf(android.content.ComponentName(a,com.abhi.ganasuno.MainActivity::class.java))))}.onFailure{toast("No browser available")}}
    private fun message(title:String,body:String){MaterialAlertDialogBuilder(a).setTitle(title).setMessage(body).setPositiveButton("Close",null).show()}
    fun show(){choose("Public catalogue · official YouTube metadata",listOf("Search music videos","Search artist channels","Search public playlists","Recent music video uploads","Popular music videos · ${region()}","Open public playlist URL / ID","Saved playlist snapshots (offline)","Set catalogue result limit","Set / replace API key","Forget API key","Clear cached playlist metadata","Discover public playlists by theme")){n->when(n){0,1,2->ask("Search query"){q->if(q.isBlank())toast("Enter a search query")else search(q,listOf("video","channel","playlist")[n])};3->ask("Recent music uploads · search artist or genre"){q->if(q.isBlank())toast("Enter a query")else task({PublicCatalogue.search(it,q,"video",region(),limit(),true)}){rows->entries("Recent uploads · last 30 days",rows)}};4->task({PublicCatalogue.popular(it,region(),limit())}){rows->entries("Popular music videos · ${region()}",rows)};5->ask("Public YouTube playlist URL or ID"){raw->val id=V8Core.playlistId(raw);if(id==null)toast("Invalid playlist reference")else playlist(id,id)};6->saved();7->choose("Maximum returned results per discovery request",listOf("10","20","30","50","100")){i->LibraryStore.option("home_limit",listOf(10,20,30,50,100)[i],true);toast("Result limit saved")};8->ask("YouTube Data API key · session only",true){raw->if(Batch16.keyLooksValid(raw)){key=raw;toast("Session key set")}else toast("Invalid API key format")};9->{generation++;key="";toast("Session key forgotten")};10->{generation++;PublicCatalogue.clear(a);toast("Cached public metadata cleared")};11->featured()}}}
    private fun curatorPrefs()=a.getSharedPreferences("curators_v23",android.content.Context.MODE_PRIVATE)
    private fun curators()=curatorPrefs().getString("ids","").orEmpty().split(',').filter{Batch16.valid("channel",it)}.distinct().take(30)
    fun curator(){val old=curators();choose("Curator channels · saved locally",listOf("Add or browse curator")+old){n->if(n==0)ask("Curator YouTube channel ID or /channel/ URL"){raw->val id=Batch22.channel(raw);if(id==null)toast("Enter a UC channel ID or channel URL")else{curatorPrefs().edit().putString("ids",Batch23.addChannel(old,id).joinToString(",")).apply();curatorActions(id)}}else curatorActions(old[n-1])}}
    private fun curatorActions(id:String){choose(id,listOf("Browse published playlists","About curator","Forget saved curator")){n->when(n){0->task({PublicCatalogue.curator(it,id,limit())}){entries("Playlists published by selected curator",it)};1->details("channel",id,id);2->{curatorPrefs().edit().putString("ids",curators().filterNot{it==id}.joinToString(",")).apply();toast("Curator forgotten")}}}}
    fun combinedInfo(song:Song){if(song.localUri.isNotBlank()||!Batch16.valid("video",song.id)){toast("Select a public video first");return};MaterialAlertDialogBuilder(a).setTitle("Fetch combined metadata?").setMessage("Public video ID is sent to YouTube, the existing extractor and Return YouTube Dislike for community estimates.").setNegativeButton("Cancel",null).setPositiveButton("Fetch"){_,_->task({key->val public=PublicCatalogue.details(key,"video",song.id);val stream=runCatching{Streams.describe(song.id)}.getOrDefault("Stream data unavailable");val community=runCatching{CommunityVideo.votes(song.id)}.getOrNull();public+"\n\nSelected stream (provider reported)\n"+stream+"\nCommunity dislike estimate: "+(community?.dislikes?.toString()?:"Unavailable")+" (not official)"}){message(song.title,it)}}.show()}
    fun charts(){val codes=listOf("IN","US","GB","JP","KR","DE","BR","CA","AU","FR","MX","ID","ZA","ES","IT");choose("Popular music videos · sampled rankings",listOf("Multi-country sample (6 markets)")+codes){n->if(n==0){task({key->val markets=listOf("IN","US","GB","JP","BR","DE");val good=markets.mapNotNull{code->runCatching{code to PublicCatalogue.popular(key,code,20)}.getOrNull()?.takeIf{it.second.isNotEmpty()}};require(good.size>=2);val byId=good.flatMap{it.second}.associateBy{it.id};Triple(good.map{it.first},Batch27.ranks(good.map{r->r.second.map{it.id}}),byId)}){(markets,ranks,byId)->choose("Sample only · ${markets.joinToString()} · not global chart",ranks.take(50).map{r->"${byId.getValue(r.id).title} · ${r.countries}/${markets.size} markets"}){i->val e=byId.getValue(ranks[i].id);entries(e.title,listOf(e))}}}else{val code=codes[n-1];task({PublicCatalogue.popular(it,code,limit())}){rows->choose("$code · API order · ${rows.size} results",Batch25.rankLabels(rows.map{e->e.title+" · "+e.channel})){i->val e=rows[i];choose(e.title,listOf("Public metadata","Open official video","Read public comments")){v->when(v){0->details("video",e.id,e.title);1->open("video",e.id);2->comments(e.id,e.title)}}}}}}}
    fun comments(id:String,title:String,parent:String="",next:String=""){
        if(!Batch25.videoId(id)){toast("No public video ID");return}
        task({PublicCatalogue.comments(it,id,next,parent)}){page->val rows=page.rows;val more=page.next.isNotBlank()&&page.next!=next;val labels=listOf(if(parent.isBlank())"+ Write public comment" else "+ Reply to thread")+rows.map{r->r.author+" · "+r.text.replace('\n',' ').take(120)}+(if(more)listOf("Next page →")else emptyList());choose(if(parent.isBlank())"Comments · $title" else "Public replies",labels){i->when{ i==0->AccountTools(a,io){null}.comment(id,title,parent);i==rows.size+1&&more->comments(id,title,parent,page.next);else->{val r=rows[i-1];val d=MaterialAlertDialogBuilder(a).setTitle(r.author).setMessage(r.text+"\n\nPublished: "+r.date+"\nLikes: "+(r.likes?.toString()?:"Unavailable")).setPositiveButton("Close",null).setNegativeButton("Reply"){_,_->AccountTools(a,io){null}.comment(id,title,parent.ifBlank{r.id})};if(parent.isBlank()&&r.replies>0)d.setNeutralButton("Read ${r.replies} replies"){_,_->comments(id,title,r.id)};d.show()}}}}
    }
    fun home(){task({PublicCatalogue.boundedHome(it,region(),limit())}){entries("Home · public music catalogue · ${it.size} results",it)}}
    fun featured(){val themes=listOf("Hindi acoustic playlist","Instrumental focus playlist","Indie music playlist","Workout music playlist","Jazz music playlist","Classical music playlist");choose("Discover public playlists · theme search (not editorial picks)",themes){n->task({PublicCatalogue.search(it,themes[n],"playlist",region(),limit())}){entries(themes[n],it)}}}
    fun search(q:String,kind:String){task({PublicCatalogue.search(it,q,kind,region(),limit())}){rows->entries("Public $kind results",rows)}}
    fun info(song:Song){if(song.localUri.isNotBlank()||!Batch16.valid("video",song.id)){toast("No public video ID");return};details("video",song.id,song.title)}
    fun alternatives(song:Song){if(song.localUri.isNotBlank()){toast("Online suggestions require a public video");return};task({val rows=PublicCatalogue.search(it,"${song.title} ${song.artist}","video",region(),limit());val ids=Batch16.alternate(song.id,song.title,rows.map{e->e.id to e.title});rows.filter{e->e.id in ids}}){rows->entries("Possible other versions · verify matches",rows)}}
    private fun details(kind:String,id:String,title:String){task({PublicCatalogue.details(it,kind,id)}){body->message(title,body)}}
    private fun entries(title:String,rows:List<PublicCatalogue.Entry>){choose(title,rows.map{e->e.title+if(e.channel.isBlank())"" else " · ${e.channel}"}){i->val e=rows[i];choose(e.title,when(e.kind){"channel"->listOf("About / channel statistics","Music videos by channel","Open official channel");"playlist"->listOf("Open playlist tracks","Playlist information","Open official playlist");else->listOf("Video information","Open official video","Browse uploader channel")}){n->when(e.kind){"channel"->when(n){0->details(e.kind,e.id,e.title);1->task({PublicCatalogue.search(it,"","video",region(),limit(),channel=e.id)}){videos->entries("${e.title} · music uploads",videos)};2->open(e.kind,e.id)};"playlist"->when(n){0->playlist(e.id,e.title);1->details(e.kind,e.id,e.title);2->open(e.kind,e.id)};else->when(n){0->details(e.kind,e.id,e.title);1->open(e.kind,e.id);2->if(Batch16.valid("channel",e.channelId))channel(e.channelId,e.channel)else toast("Uploader ID unavailable")}}}}}
    fun channel(id:String,title:String){choose(title,listOf("About / statistics","Music videos","Open channel")){n->when(n){0->details("channel",id,title);1->task({PublicCatalogue.search(it,"","video",region(),limit(),channel=id)}){entries("$title · music uploads",it)};2->open("channel",id)}}}
    fun playlist(id:String,title:String){val cached=PublicCatalogue.cached(a,id);choose(title,listOf("Fetch or refresh public tracks","Show saved metadata (expires in 7 days)","Bookmark this playlist","Open official playlist")){n->when(n){0->task({PublicCatalogue.playlist(it,id,200)}){rows->MaterialAlertDialogBuilder(a).setTitle("Public playlist · ${rows.size} results").setMessage("Save this metadata for up to seven days? No audio is stored. The API may omit private or deleted entries.").setNegativeButton("View only"){_,_->entries(title,rows)}.setPositiveButton("Save and view"){_,_->PublicCatalogue.save(a,id,rows);bookmark(id,title);entries(title,rows)}.show()};1->if(cached==null)toast("No fresh snapshot. Refresh online first.")else entries("Saved metadata · $title",cached);2->bookmark(id,title);3->open("playlist",id)}}}
    private fun bookmark(id:String,title:String){LibraryStore.saveCollection("Playlist",title.take(120).ifBlank{id},Batch16.publicUrl("playlist",id));toast("Playlist bookmarked")}
    private fun saved(){val refs=LibraryStore.collections().filter{it.kind=="Playlist"&&V8Core.playlistId(it.url)!=null};choose("Saved public playlists",refs.map{it.title}){n->val r=refs[n];V8Core.playlistId(r.url)?.let{playlist(it,r.title)}}}
}
